def _lex(s):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if "0" <= c <= "9":
            j = i + 1
            while j < n and "0" <= s[j] <= "9":
                j += 1
            toks.append(("num", int(s[i:j])))
            i = j
            continue
        if "A" <= c <= "Z":
            j = i + 1
            while j < n and "A" <= s[j] <= "Z":
                j += 1
            if j == i + 1 and j < n and "0" <= s[j] <= "9":
                k = j + 1
                while k < n and "0" <= s[k] <= "9":
                    k += 1
                toks.append(("cell", s[i:k]))
                i = k
                continue
            toks.append(("func", s[i:j]))
            i = j
            continue
        two = s[i:i + 2]
        if two in ("<>", "<=", ">="):
            toks.append(("cmp", two))
            i += 2
            continue
        if c in "=<>":
            toks.append(("cmp", c))
            i += 1
            continue
        if c in "+-*/":
            toks.append(("op", c))
            i += 1
            continue
        if c == "(":
            toks.append(("lp",))
            i += 1
            continue
        if c == ")":
            toks.append(("rp",))
            i += 1
            continue
        if c == ",":
            toks.append(("comma",))
            i += 1
            continue
        if c == ":":
            toks.append(("colon",))
            i += 1
            continue
        raise ValueError(s[i:])
    return toks


def _expand(a, b):
    c1, r1 = ord(a[0]) - ord("A"), int(a[1:])
    c2, r2 = ord(b[0]) - ord("A"), int(b[1:])
    if c1 > c2:
        c1, c2 = c2, c1
    if r1 > r2:
        r1, r2 = r2, r1
    out = []
    for r in range(r1, r2 + 1):
        row = str(r)
        for c in range(c1, c2 + 1):
            out.append(chr(ord("A") + c) + row)
    return out


def _parse(s):
    toks = _lex(s)
    n = len(toks)
    p = 0

    def peek():
        return toks[p] if p < n else None

    def pop():
        nonlocal p
        t = toks[p]
        p += 1
        return t

    def parse_expr():
        node = parse_term()
        while True:
            t = peek()
            if t is None or t[0] != "op" or t[1] not in "+-":
                return node
            op = pop()[1]
            node = ("bin", op, node, parse_term())

    def parse_term():
        node = parse_unary()
        while True:
            t = peek()
            if t is None or t[0] != "op" or t[1] not in "*/":
                return node
            op = pop()[1]
            node = ("bin", op, node, parse_unary())

    def parse_unary():
        flips = 0
        while True:
            t = peek()
            if t is not None and t[0] == "op" and t[1] == "-":
                pop()
                flips += 1
            else:
                break
        node = parse_atom()
        for _ in range(flips):
            node = ("neg", node)
        return node

    def parse_atom():
        t = pop()
        if t[0] == "num":
            return ("num", t[1])
        if t[0] == "cell":
            return ("cell", t[1])
        if t[0] == "lp":
            node = parse_expr()
            pop()
            return node
        name = t[1].upper()
        pop()
        if name == "IF":
            left = parse_expr()
            cmpop = pop()[1]
            right = parse_expr()
            pop()
            then_e = parse_expr()
            pop()
            else_e = parse_expr()
            pop()
            return ("IF", left, cmpop, right, then_e, else_e)
        args = []
        while True:
            args.append(parse_arg())
            t2 = peek()
            if t2 is not None and t2[0] == "comma":
                pop()
                continue
            break
        pop()
        return ("call", name, tuple(args))

    def parse_arg():
        t = peek()
        if t is not None and t[0] == "cell" and p + 1 < n and toks[p + 1][0] == "colon":
            a = pop()[1]
            pop()
            b = pop()[1]
            return ("range", _expand(a, b))
        return parse_expr()

    return parse_expr()


def _div(a, b):
    # Truncate toward zero. Python's // floors.
    if b == 0:
        return "#DIV/0!"
    q = abs(a) // abs(b)
    return -q if (a < 0) ^ (b < 0) else q


def _apply(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    return _div(a, b)


def _cmp(op, a, b):
    if op == "=":
        return a == b
    if op == "<>":
        return a != b
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    return a >= b


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    asts = {}
    lits = {}
    for name, raw in cells.items():
        if raw.startswith("="):
            asts[name] = _parse(raw[1:])
        else:
            lits[name] = int(raw)

    memo = {}
    visiting = set()

    def drive(node, stack, ops):
        kind = node[0]
        if kind == "num":
            stack.append(node[1])
            return
        if kind == "cell":
            name = node[1]
            if name in memo:
                stack.append(memo[name])
                return
            if name in visiting:
                stack.append("#CYCLE!")
                return
            if name in lits:
                val = lits[name]
                memo[name] = val
                stack.append(val)
                return
            if name not in asts:
                stack.append(0)
                return
            visiting.add(name)
            ops.append(("store", name))
            ops.append(("eval", asts[name]))
            return
        if kind == "neg":
            ops.append(("neg",))
            ops.append(("eval", node[1]))
            return
        if kind == "bin":
            ops.append(("bin_left", node[1], node[3]))
            ops.append(("eval", node[2]))
            return
        if kind == "IF":
            ops.append(("if_left", node[2], node[3], node[4], node[5]))
            ops.append(("eval", node[1]))
            return
        tasks = []
        for arg in node[2]:
            if arg[0] == "range":
                for nm in arg[1]:
                    if nm in cells:
                        tasks.append(("c", nm))
            else:
                tasks.append(("e", arg))
        ops.append(("agg_step", node[1], tasks, 0, None))

    def run(node):
        stack = []
        ops = [("eval", node)]
        while ops:
            step = ops.pop()
            tag = step[0]
            if tag == "eval":
                drive(step[1], stack, ops)
            elif tag == "store":
                memo[step[1]] = stack[-1]
                visiting.remove(step[1])
            elif tag == "neg":
                v = stack.pop()
                stack.append(v if isinstance(v, str) else -v)
            elif tag == "bin_left":
                if not isinstance(stack[-1], str):
                    ops.append(("bin_do", step[1]))
                    ops.append(("eval", step[2]))
            elif tag == "bin_do":
                right = stack.pop()
                left = stack.pop()
                if isinstance(right, str):
                    stack.append(right)
                else:
                    stack.append(_apply(step[1], left, right))
            elif tag == "if_left":
                if not isinstance(stack[-1], str):
                    leftv = stack.pop()
                    ops.append(("if_right", step[1], leftv, step[3], step[4]))
                    ops.append(("eval", step[2]))
            elif tag == "if_right":
                rightv = stack.pop()
                if isinstance(rightv, str):
                    stack.append(rightv)
                else:
                    branch = step[3] if _cmp(step[1], step[2], rightv) else step[4]
                    ops.append(("eval", branch))
            elif tag == "agg_step":
                _tag, fn, tasks, i, acc = step
                if i >= len(tasks):
                    stack.append(0 if acc is None else acc)
                else:
                    ops.append(("agg_got", fn, tasks, i, acc))
                    task = tasks[i]
                    if task[0] == "c":
                        ops.append(("eval", ("cell", task[1])))
                    else:
                        ops.append(("eval", task[1]))
            else:
                _tag, fn, tasks, i, acc = step
                v = stack.pop()
                if isinstance(v, str):
                    stack.append(v)
                else:
                    if acc is None:
                        acc = v
                    elif fn == "SUM":
                        acc += v
                    elif fn == "MIN":
                        if v < acc:
                            acc = v
                    elif v > acc:
                        acc = v
                    ops.append(("agg_step", fn, tasks, i + 1, acc))
        return stack[-1]

    for name in cells:
        if name not in memo:
            run(("cell", name))
    return {name: memo[name] for name in cells}
